package handler

import (
  "log"
  "net/http"

  "github.com/gin-gonic/gin"
)

type Auditor interface {
  Record(userID, path, ip string) error
}

func Export(a Auditor) gin.HandlerFunc {
  return func(c *gin.Context) {
    go func() {
      if err := a.Record(c.GetString("userID"), c.FullPath(), c.ClientIP()); err != nil {
        log.Printf("audit: %v", err)
      }
    }()
    c.JSON(http.StatusAccepted, gin.H{"status": "accepted"})
  }
}

