type Auditor interface {
  Record(ctx context.Context, userID, path, ip string) error
}

func Export(a Auditor) gin.HandlerFunc {
  return func(c *gin.Context) {
    cp := c.Copy()
    ctx := context.WithoutCancel(cp.Request.Context())
    go func() {
      if err := a.Record(ctx, cp.GetString("userID"), cp.FullPath(), cp.ClientIP()); err != nil {
        log.Printf("audit: %v", err)
      }
    }()
    c.JSON(http.StatusAccepted, gin.H{"status": "accepted"})
  }
}
